import logging
import sys
import time
import traceback
from threading import Lock

import six

from ta_ue_plugin_android.uepc.adb_proxy import NAA_PACKAGE_NAME
from ta_ue_plugin_android.uepc.datatransfer.iperf_options import LINUX_CONGESTION, IPERF3_LINUX_CONGESTION
from ta_ue_plugin_android.uepc.datatransfer.data_transfer_utils import Watchdog, \
    IperfServerReportParser, FreeTcpPortFinder, IperfProcessKiller
from ta_ue_plugin_android.uepc.ssh_manager import SshManagerException
from ta_ue_plugin_android.uepc.ue_manager_exceptions import DtNotProcessingInternalException, IperfClientStuckException, \
    IperfServerStuckException, KillProcessFailException, IperfConnectFailed, IperfCongestionIncorrectProtocol, \
    IperfCongestionAlgorithmNotFound, NoFreePortException, NegativeThroughputValuesFromApp
from ta_ue_plugin_android.uepc.ue_pc_logger import LoggerAdapter4EmptyExtra

IPERF_OUTPUT_CONNECT_FAILED = 'connect failed'
IPERF_CONFGESTION_SET_FAILURE_PROTOCOL = 'congestion control failed: Protocol not available'
IPERF_CONFGESTION_SET_FAILURE_NOT_AVAILABLE = 'congestion control failed: No such file or directory'
CONFLUENCE_PAGE = \
    'https://confluence.ext.net.nokia.com/pages/viewpage.action?pageId=818442194#id-5.Tools-HowtouploadiperftoUEandusewithta_ue_plugin_android'
MAX_IPERF_INTERVALS_DELAY = 30


class DataTransferItem(object):
    # pylint: disable=too-many-instance-attributes
    """DataTransferItem"""

    def __init__(self, dt_config, uecontrol, ssh_manager, dt_name="DT_name"):
        """

        :param dt_config:
        :param uecontrol:
        :param ssh_manager:
        :param dt_name:
        """
        raw_logger = logging.getLogger("ute_ue.uepc")
        self.dt_name = dt_name
        self.uecontrol = uecontrol
        self.logger = LoggerAdapter4EmptyExtra(raw_logger, {'area': 'DATATRANSFER {}'.format(dt_name),
                                                            'ue_id': self.uecontrol.get_debug_id()})
        self.logger.info("Creating DataTransferItem for {}".format(uecontrol.get_debug_id() + dt_name))
        self.finish = False
        self._closed = False
        self.action_index = 0
        self.direction_specific = DataTransferItemDirectionSpecific(dt_config, uecontrol, ssh_manager, dt_name="DT")
        self.server_lines = []
        self.client_lines = []
        self.client_out = None
        self.server_out = None
        self.server_parent_pid = None
        self.client_parent_pid = None
        self.iperf_cmds = {}
        self.has_raised = False
        self.to_raise_tuple = None
        self.debug_desc = 'no debug desc'
        self.dt_config = dt_config
        self.dt_config.validate_bandwidth_set_for_udp()
        self.actions_sequence = [self._start_free_port_search_on_server, self._get_netstat_output_from_server,
                                 self._start_free_port_search_on_server_with_get_pty,
                                 self._get_netstat_output_from_server, self._set_iperf_port, self._start_iperf_server,
                                 self._wait_for_iperf_server_startup, self._start_iperf_client,
                                 self._wait_for_iperf_client_startup, self._read_client_and_server_out,
                                 self._server_close_delay_if_need, self.count_datatransfer_statistics,
                                 self._mark_data_transfer_finish]
        self.watch_dog = Watchdog()
        self.closing_lock = Lock()
        self.port = self._get_predefined_port_value()
        self.last_client_read_time = None
        self.last_server_read_time = None
        self.client_start_time = None
        self.client_finish_time = None
        self.avg_throughput = None
        self.datagram_loss = None
        self._server_delay_start_waiting_time = 0  # using only by _server_close_delay_if_need
        self.logger.info("Created DataTransferItem for {}".format(self.uecontrol.get_debug_id()))
        self.iperf_report_parser = IperfServerReportParser()
        self.client_delay = self.dt_config.get_iperf_interval() * MAX_IPERF_INTERVALS_DELAY
        self.server_delay = self._get_allowed_server_response_delay()

    def process_data_transfer(self):
        """Doing next process step"""
        self.watch_dog.update()
        if self.closing_lock.locked():
            debug_msg_pattern = "process_data_transfer closing_lock is locked, direction: {}, self.action_index = {}"
            self.logger.debug(debug_msg_pattern.format(self.dt_config.get_direction(), self.action_index))
            return
        with self.closing_lock:
            if self.action_index < len(self.actions_sequence):
                self.logger.debug("process_data_transfer, direction: {}, self.action_index = {}".format(
                    self.dt_config.get_direction(), self.action_index))
                try:
                    self.actions_sequence[self.action_index]()
                except SshManagerException:
                    self.logger.warning("SshManagerException, self.action_index = {}".format(self.action_index))
                    return
                debug_msg = "process_data_transfer finish, direction: {}, self.action_index = {}".format(
                    self.dt_config.get_direction(), self.action_index)
                self.logger.debug(debug_msg)

    def is_finish(self):
        """
        Check if this dt has been starvation
        :return:
        """
        if not self.finish and self.watch_dog.is_timeout():
            raise DtNotProcessingInternalException("Data transfer was not processing too long time, {} sec".format(
                time.time() - self.watch_dog.get_last_update_time()))
        return self.finish

    def get_completion_percentage(self, rows):
        """The method returns the ration of duration to last interval end time which is the % of completion"""
        return self.iperf_report_parser.get_duration_to_last_interval_end_time_ratio(rows,
                                                                                     self.dt_config.get_duration())

    def is_iperf_client_started(self):
        """Check if iperf client is started"""
        self.logger.debug("is_iperf_client_started? self.last_client_read_time: {}".format(self.last_client_read_time))
        self.logger.debug("client_lines: {}".format(self.client_lines))
        if self.dt_config.iperf_version == 2:
            return self.is_iperf2_client_connected()
        if self.dt_config.iperf_version == 3:
            return self.is_iperf3_client_connected()
        return False

    def is_iperf2_client_connected(self):
        for line in self.client_lines:
            if "Client connecting" in line:
                return True
        return False

    def is_iperf3_client_connected(self):
        for line in self.client_lines:
            if "Connecting to host {}".format(self.direction_specific.get_server_ip()) in line:
                return True
        return False

    def is_iperf_server_started(self):
        """Check if iperf server is started"""
        self.logger.debug("is_iperf_server_started? self.last_serer_read_time: {}".format(self.last_server_read_time))
        self.logger.debug("server_lines: {}".format(self.server_lines))
        for line in self.server_lines:
            if self.dt_config.iperf_version == 3 and "Linux" in line:
                return True
            elif "Server listening" in line:
                return True
        return False

    def _get_netstat_output_from_server(self):
        if self.port:
            self.action_index += 1
            return
        self.logger.debug("Awaiting for netstat output on server side")
        if not self.server_lines:
            self._read_server_out()
        self.action_index += 1
        time.sleep(0.1)

    # Temporary resolution for iperf port searching for newer androids
    def _set_iperf_port_tmp(self):
        self.logger.debug("Setting iperf port without netstat: _set_iperf_port_tmp.")

        port_finder = FreeTcpPortFinder()
        self.logger.debug("Setting random port from 50000-60000 range.")
        self.port = port_finder.find_random_free_port_tmp(self.uecontrol)
        self.action_index += 1

    def _set_iperf_port(self):
        self.logger.debug("Setting iperf port for data transfer.")
        if self.port:
            self.action_index += 1
            return

        # Checking version of NAA is a temporary resolution for iperf port searching for newer androids
        # Upd: version code is checked instead of version name: https://jiradc.ext.net.nokia.com/browse/NAA-326
        if type(self.uecontrol).__name__ == 'AndroidControl' \
                and self.dt_config.get_direction() == 'dl' \
                and self.uecontrol.get_mobile_app_package_name() == NAA_PACKAGE_NAME \
                and self.uecontrol.ueman.get_mobile_app_protocol_version() > 9:
            self._set_iperf_port_tmp()
            return

        port_finder = FreeTcpPortFinder()
        self.logger.debug("Setting random port from 50000-60000 range.")
        self.port = port_finder.find_random_free_port_from_cmd_results(self.server_lines)
        self.action_index += 1

    def _get_predefined_port_value(self):
        """Get port either from robot keyword argument or yaml iperf_options -> qci"""
        port = self.dt_config.robot_kwargs.get("port")
        if port:
            self.logger.debug("Got port based on robot port keyword argument: {}".format(port))
            return int(port)
        if self.dt_config.has_qci_value():
            port = self.dt_config.get_qci_port()
            self.logger.debug("Getting port based on qci {} value to:  {}".format(self.dt_config.get_qci_value(), port))
            return int(port)

    def _start_free_port_search_on_server(self):
        """Returns all ports from netstat -an output"""
        if self.port:
            self.action_index += 1
            return
        self.logger.debug("Running netstat on server to get free ports")
        self.server_out = self.direction_specific.run_cmd_on_server(FreeTcpPortFinder.get_netstat_cmd(), echo_pid=False)
        self.action_index += 1

    def _start_free_port_search_on_server_with_get_pty(self):
        """Returns all ports from netstat -an output"""
        if self.port:
            self.action_index += 1
            return
        if not self.server_lines:
            self.logger.debug("Getting netstat output with get_pty option")
            self.server_out = self.direction_specific.run_cmd_on_server(FreeTcpPortFinder.get_netstat_cmd(),
                                                                        echo_pid=False,
                                                                        get_pty=True)
        self.action_index += 1

    def _start_iperf_server(self):
        cmd = self.direction_specific.create_iperf_server_cmd(self.port)  # XXX2
        self.iperf_cmds['server'] = cmd
        self.logger.debug("_start_iperf_server, direction=%s cmd = %s" % (self.dt_config.get_direction(), cmd))
        self.server_out = self.direction_specific.run_cmd_on_server(cmd)
        self.server_lines = []
        self.action_index += 1

    def _wait_for_iperf_server_startup(self):
        self.logger.debug("Awaiting for iperf server start")
        self._read_server_out()
        self._validate_iperf_present_and_executable(self.server_lines, who='server')
        self._validate_port_in_use(self.server_lines)
        self._verify_server_out_is_alive()
        if self.is_iperf_server_started():
            time.sleep(2)  # Server may need some more time to start before client is able to connect
            self.action_index += 1
        time.sleep(0.5)

    def _wait_for_iperf_client_startup(self):
        self.logger.debug("Awaiting for iperf client start")
        self._read_client_out()
        self._validate_iperf_present_and_executable(self.client_lines, who='client')
        self._validate_connection_ok(self.client_lines, who='client')
        self._validate_linux_congestion_algorithm(self.client_lines)
        self._verify_client_out_is_alive()
        if self.is_iperf_client_started():
            self.client_start_time = time.time()
            self.action_index += 1
        time.sleep(0.5)

    def _start_iperf_client(self):
        cmd = self.direction_specific.create_iperf_client_cmd(self.port)
        self.iperf_cmds['client'] = cmd
        self.logger.debug("_start_iperf_client, direction=%s cmd = %s" % (self.dt_config.get_direction(), cmd))
        self.client_out = self.direction_specific.run_cmd_on_client(cmd)
        self.client_lines = []
        self.last_client_read_time = time.time()
        self.action_index += 1

    def _server_close_delay_if_need(self):
        if not self.dt_config.has_server_close_delay():
            self.action_index += 1
            return
        if self._server_delay_start_waiting_time == 0:
            self._server_delay_start_waiting_time = time.time()
        server_delay_time = int(self.dt_config.get_server_close_delay())
        if time.time() < server_delay_time + self._server_delay_start_waiting_time:
            self._read_server_out()
            self.logger.debug(
                "waiting for server finish in  _server_close_delay_if_need, waited {} seconds".format(
                    time.time() - self._server_delay_start_waiting_time))
            time.sleep(float(self.dt_config.get_iperf_interval()) / 2)
            return
        self.action_index += 1

    # DOWNLINK & UPLINK PART
    def _read_client_and_server_out(self):
        """Updates and validate client and server outputs"""
        self.logger.debug('Started to read client and server outputs')
        sleep_time = float(self.dt_config.get_iperf_interval()) / 2
        self._read_server_out()
        self._read_client_out()
        if self.client_out.is_finish():
            self.client_finish_time = time.time()
            self.logger.debug('Data transfer finished')
            if self.dt_config.is_downlink():
                lines = self.client_out.really_read_lines()
                self._log_lines(lines, 'read iperf client (ssh) AFTER CLOSE: ')
                self.client_lines += lines
            self.action_index += 1
        self._verify_client_out_is_alive()
        self._verify_server_out_is_alive()
        time.sleep(sleep_time)

    def _verify_client_out_is_alive(self):
        if self.last_client_read_time is not None:
            if time.time() - self.last_client_read_time > self.client_delay:
                self._raise_iperf_client_stuck()
            return
        self.logger.debug("Client didn't start yet.")

    def _verify_server_out_is_alive(self):
        if self.last_server_read_time is not None:
            if time.time() - self.last_server_read_time > self.server_delay:
                self._raise_iperf_server_stuck()
            return
        self.logger.debug("Server didn't start yet.")

    def _get_allowed_server_response_delay(self):
        if self.dt_config.has_server_close_delay():
            server_close_delay = int(self.dt_config.get_server_close_delay())
            if server_close_delay > 0:
                return server_close_delay + self.dt_config.get_iperf_interval() * MAX_IPERF_INTERVALS_DELAY
        return self.dt_config.get_iperf_interval() * MAX_IPERF_INTERVALS_DELAY

    def _read_client_out(self, log_msg='read iperf client: '):
        lines = self.client_out.read_lines()
        self._log_lines(lines, log_msg)
        self.client_lines += lines
        if lines:
            self.last_client_read_time = time.time()
            for line in lines:
                if "write failed" in line:
                    self._raise_iperf_client_write()

    def _read_server_out(self, log_msg='read iperf server: '):
        lines = self.server_out.read_lines()
        self._log_lines(lines, log_msg)
        self.server_lines += lines
        if lines:
            self.last_server_read_time = time.time()

    def _raise_iperf_client_write(self):
        msg = 'Iperf client did not receive the last datagram.\n' \
              'The connection to the mobile network may have been interrupted.\n' \
              'Please verify your network connectivity between client and server.\n' \
              'This is for data transfer name: {}'.format(self.dt_name)
        raise IperfClientStuckException(msg)

    def _raise_iperf_client_stuck(self):
        msg = 'Iperf client was not receiving data for more than: {}s.\n' \
              'Please verify your network connectivity between client and server.\n' \
              'This is for data transfer name: {}'.format(self.client_delay, self.dt_name)
        raise IperfClientStuckException(msg)

    def _raise_iperf_server_stuck(self):
        msg = "Iperf server was not receiving data for more than: {}s.\n" \
              "Please verify your network connectivity between client and server.\n" \
              "This is for data transfer name: {}".format(self._get_allowed_server_response_delay(), self.dt_name)
        raise IperfServerStuckException(msg)

    def _log_lines(self, lines, msg):
        for line in lines:
            self.logger.debug(msg + line)

    def _get_reports_to_log(self):
        return "SERVER REPORT:\n%s\n\nCLIENT REPORT:\n%s" % ('\n'.join(self.server_lines), '\n'.join(self.client_lines))

    def count_datatransfer_statistics(self):
        """Parses the iperf report and counts statistics based on that"""
        self.logger.debug("Counting data transfer stats.")
        traffic_type = self.dt_config.get_traffic_type()
        is_parallel_streams = self.dt_config.is_parallel_streams_datatransfer()
        if self.dt_config.is_udp():
            server_rows = self._parse_and_validate_rows(traffic_type, is_parallel_streams=is_parallel_streams,
                                                        get_datagram_loss=True)
            self.datagram_loss = self.count_datagram_loss(server_rows)
        server_rows = self._parse_and_validate_rows(traffic_type, is_parallel_streams=is_parallel_streams)
        self.avg_throughput = self.count_avg_throughput(server_rows)
        self.action_index += 1

    def _mark_data_transfer_finish(self):
        self.finish = True

    def _parse_and_validate_rows(self, traffic_type=None, is_parallel_streams=False, get_datagram_loss=False):
        if traffic_type == 'nbiot':
            server_lines = self.iperf_report_parser.get_server_lines_with_correct_port(self.server_lines[:],
                                                                                       self.client_lines[:])
            rows = self._parse_nbiot_traffic_rows(server_lines, is_parallel_streams, include_nans=False)
            self.iperf_report_parser.validate_server_rows(rows, server_lines, inner_rows=False, first_row=False)
            return rows
        rows = self.iperf_report_parser.parse_to_rows(self.server_lines[:],
                                                      parallel_streams=is_parallel_streams,
                                                      get_datagram_loss=get_datagram_loss)
        self.iperf_report_parser.validate_server_rows(rows, self.server_lines[:], inner_rows=not is_parallel_streams)
        return rows

    def _parse_nbiot_traffic_rows(self, server_lines, is_parallel_streams, include_nans=False):
        self.logger.debug('_parse_and_validate_rows, traffic_type=nbiot')
        all_rows = self.iperf_report_parser.parse_to_rows(server_lines, parallel_streams=is_parallel_streams,
                                                          include_nans=include_nans)
        rows = self._remove_inner_summary_rows(all_rows)
        self.iperf_report_parser.validate_server_rows(rows, server_lines, inner_rows=False, first_row=False)
        return rows

    def _validate_iperf_present_and_executable(self, output_lines, who='unknown'):
        self.logger.debug('starting to validate lines in _validate_iperf_present_and_executable')
        for line in output_lines:
            lines = ''.join(line)
            if 'not found' in lines:
                msg = 'Iperf not found. Unable to start {} data transfer.\n'.format(self.dt_name)
                if self.dt_config.iperf_path:
                    msg = msg + "Please verify if iperf is available at:\n" \
                                "{} on {} UE.".format(self.dt_config.iperf_path, self.uecontrol.get_debug_id())
                raise Exception(msg)
            if 'Permission denied' in lines:
                msg = 'Unable to run iperf (Permission denied) on {} UE\n' \
                      '{} data transfer on {} side.\n'.format(self.uecontrol.get_debug_id(), self.dt_name, who)
                if self.dt_config.iperf_path:
                    msg = msg + "Please verify if iperf binary has executable permissions:\n" \
                                "{}".format(self.dt_config.iperf_path)
                raise Exception(msg)

    def _validate_port_in_use(self, output_lines):
        self.logger.debug('starting to validate lines in validate_port_in_use')
        for line in output_lines:
            lines = ''.join(line)
            if 'Address already in use' in lines:
                msg = 'Iperf port {} is already in use. Unable to start {} data transfer.\n' \
                      'Please check iperf server for the port occupancy.'.format(self.port, self.dt_name)
                raise NoFreePortException(msg)

    def _validate_connection_ok(self, output_lines, who='unknown'):
        self.logger.debug('starting to validate lines in _validate_connection_ok')
        for line in output_lines:
            if IPERF_OUTPUT_CONNECT_FAILED in line:
                msg = "Iperf {} unable to connect during {} data transfer: {}\n" \
                      "Please verify network connectivity between client and server.\n" \
                      "Try to run data transfer manually before retrying automation.\n" \
                      "IPERF REPORTS:\n{}"
                raise IperfConnectFailed(msg.format(who, self.dt_name, line, self._get_reports_to_log()))

    def _validate_linux_congestion_algorithm(self, output_lines):
        if self._is_iperf_client_additional_option_available(LINUX_CONGESTION) or \
                self._is_iperf_client_additional_option_available(IPERF3_LINUX_CONGESTION):
            for line in output_lines:
                if IPERF_CONFGESTION_SET_FAILURE_PROTOCOL in line:
                    msg = "{}\n" \
                          "Please make sure to use TCP protocol.".format(line)
                    raise IperfCongestionIncorrectProtocol(msg)
                if IPERF_CONFGESTION_SET_FAILURE_NOT_AVAILABLE in line:
                    SUPPORTED_ALGOS_CMD = "sysctl net.ipv4.tcp_available_congestion_control"
                    supported_algo = self.direction_specific.run_cmd_on_client(SUPPORTED_ALGOS_CMD,
                                                                               blocking=True, echo_pid=False,
                                                                               expect_output=False)
                    msg = "{}\n" \
                          "Congestion algorithm not found. Please make sure to use supported algorithm:\n" \
                          "{}".format(line, ''.join(supported_algo))
                    raise IperfCongestionAlgorithmNotFound(msg)

    def _is_iperf_client_additional_option_available(self, additional_option):
        return any([additional_option in option for option in self.dt_config.additional_iperf_options_client])

    def _remove_inner_summary_rows(self, rows):
        for row in rows[1:-1]:
            if float(row.interval_start) == 0.0 and float(row.interval_end) != float(
                    self.dt_config.get_iperf_interval()):
                rows.remove(row)
        return rows

    def count_avg_throughput(self, server_rows, omit=0, end=0, tput_collection_src="iperf"):
        """Counts average throughput from iperf reports or app's reported data"""
        omit = int(omit)
        end = int(end)
        if tput_collection_src == self.dt_config.CONTROL_APP_LABEL \
                or self.dt_config.get_throughput_collection_source() == self.dt_config.CONTROL_APP_LABEL:
            return self.count_throughput_from_control_app(self._get_client_connected_duration(),
                                                          self.dt_config.get_direction(), omit=omit, end=end)
        if not server_rows:
            return -1
        interval = self.dt_config.get_iperf_interval()
        skipped_rows_counter = 0
        if (omit / interval) >= 1:
            skipped_rows_counter = omit / interval
        count_to_this_row = 0
        if (end / interval) >= 1:
            count_to_this_row = end / interval
        self.avg_throughput = self.iperf_report_parser.count_avg_throughput(server_rows,
                                                                            skipped_rows_counter=skipped_rows_counter,
                                                                            count_to_this_row=count_to_this_row)
        return self.avg_throughput

    def count_throughput_from_control_app(self, seconds, direction, omit=0, end=0):
        """Count throughput based on data collected from UE control application"""
        if self.client_finish_time:
            delay = int(time.time() - self.client_finish_time)
        else:
            delay = 0
        measured_throughput_data_bps = self.uecontrol.get_mobile_app_average_throughput(seconds, direction)
        measured_throughput_data_bps = measured_throughput_data_bps[delay:]
        self.logger.debug("Counting avg throughput based on app's measured data.\n"
                          "From data points (bps): {}".format(measured_throughput_data_bps))
        throughput_data_bps_filtered = self._filter_negative_throughput_values(measured_throughput_data_bps)
        if end == 0:
            data_to_parse = throughput_data_bps_filtered[omit:]
        else:
            data_to_parse = throughput_data_bps_filtered[omit:end]
        self.avg_throughput = \
            round(float(float(sum(data_to_parse)) / len(data_to_parse)), 2)
        return self.avg_throughput

    def _filter_negative_throughput_values(self, measured_throughput_data_bps):
        valid_values = list()
        negative_values = list()

        for tput_data in measured_throughput_data_bps:
            if tput_data < 0:
                negative_values.append(tput_data)
            else:
                valid_values.append(tput_data)
        if negative_values:
            self.logger.debug("Negative throughput values measured by app which has been removed from calculation: "
                              "{}".format(negative_values))
        if len(negative_values)/len(measured_throughput_data_bps) > 0.05:
            raise NegativeThroughputValuesFromApp("There are more then 5% throughput values measured by app which has "
                                                  "negative values: {}".format(negative_values))
        return valid_values

    def get_rows_depending_on_traffic_type(self):
        """Method's name says everything."""
        if self.dt_config.get_traffic_type() == 'nbiot':
            return self.iperf_report_parser.parse_to_rows(self.server_lines[:],
                                                          self.dt_config.is_parallel_streams_datatransfer(),
                                                          include_nans=False)
        return self.iperf_report_parser.parse_to_rows(self.server_lines[:],
                                                      self.dt_config.is_parallel_streams_datatransfer(),
                                                      include_nans=True)

    def count_datagram_loss(self, server_rows):
        """Counts datagram loss from server report"""
        self.datagram_loss = self.iperf_report_parser.count_datagram_loss(server_rows)
        return self.datagram_loss

    def get_data_transfer_statistics(self, server_rows):
        """Return string with dt statistics: avg,min,max;comma-delimited list of bits/s for all intervals"""
        if not server_rows:
            return str()
        return self.iperf_report_parser.get_data_transfer_statistics(server_rows)

    def save_exception(self, a1, b1, c1):
        """Save excpetion to be throwen by  raise_exception()"""
        self.has_raised = True
        self.to_raise_tuple = a1, b1, c1
        try:
            self.close_dt_item()
        except KillProcessFailException as e:
            trace = traceback.format_exc()
            self._log_kill_process_fail(e, trace)
        except Exception as e:  # pylint: disable=broad-except
            a, b, c = sys.exc_info()
            self._log_unexpected_exception(a, b, c, e)

    def _log_unexpected_exception(self, a, b, c, e):
        self.logger.warning("unexpectd Exception while saving exception {} {}".format(e, c))
        six.reraise(a, b, c)

    def _log_kill_process_fail(self, e, trace):
        self.logger.warning("KillProcessFailException while saving exception {} {}".format(e, trace))

    def close_dt_item(self):
        """Close cmd sessions using by this object"""
        self.logger.debug("closing dt item, getting into closing lock")
        self.finish = True
        with self.closing_lock:
            self.logger.debug("closing dt item, success got into closing lock")
            if self._closed:
                return
            self.logger.debug("Killing iperf server")
            iperf_killer = IperfProcessKiller(self.direction_specific.run_cmd_on_server, self.dt_config,
                                              dt_name=self.dt_name)
            iperf_killer.kill_server(self._get_ssh_session_pid(self.server_lines))

            if self.client_out and not self.client_out.is_finish():
                self.logger.debug("Killing iperf client")
                iperf_killer.set_lambda_run_cmd(self.direction_specific.run_cmd_on_client)
                iperf_killer.kill_client(self._get_ssh_session_pid(self.client_lines))
            self._closed = True
            self._close_client_and_server_out()

    def _close_client_and_server_out(self):
        if self.client_out:
            self.client_out.close()
        self.logger.debug("closing dt item: client out is closed")
        if self.server_out:
            self.server_out.close()
        self.logger.debug("closing dt item: server out is closed")

    def _get_client_connected_duration(self):
        if not self.client_start_time:
            return 0.0
        # Delay from start time to current time
        return time.time() - self.client_start_time

    def raise_exception(self):
        """Raise exception if stored."""
        if self.has_raised:  # TODO: exchange to 'if not isinstance(self.raised_exception, NoException):' and remove self.has_raised (also from tests)
            a, b, c = self.to_raise_tuple
            six.reraise(a, b, c)

    def __repr__(self):
        return "{} {}".format(super(DataTransferItem, self).__repr__(), self.debug_desc)

    def __str__(self):
        return "{} {}".format(super(DataTransferItem, self).__str__(), self.debug_desc)

    def _get_ssh_session_pid(self, output_lines, who='unknown'):
        try:
            return int(output_lines[0])
        except (ValueError, IndexError):
            self.logger.debug('Failed to get {} parent pid. Seems that shell session has not started yet'.format(who))
            return None


class DataTransferItemDirectionSpecific(object):
    """DataTransferItemDirectionSpecific"""

    def __init__(self, dt_config, uecontrol, ssh_manager, dt_name="DT"):
        """

        :param dt_config:
        :param uecontrol:
        :param ssh_manager:
        """
        raw_logger = logging.getLogger("ute_ue.uepc")
        self.logger = LoggerAdapter4EmptyExtra(raw_logger, {'area': 'DATATRANSFER {}'.format(dt_name)})
        self.uecontrol = uecontrol
        self.ssh_manager = ssh_manager
        self.dt_config = dt_config
        self.logger.debug('Data transfer config:\n{}'.format(self.dt_config))
        self.network_interface_name = self.get_network_interface()
        self.ip_version = self.get_ip_version()
        self.apn = self.get_apn()
        self.logger.debug('in DataTransferItemDirectionSpecific __init__ iperf_interface_name: {}'.format(
            self.network_interface_name))
        self._setup_ip_interface()
        self.logger.debug("Getting UE IP")
        self.ue_ip = self.uecontrol.get_ip(ip_version=self.ip_version,
                                           interface_name_pattern=self.network_interface_name, apn_name=self.apn)
        self.logger.debug("UE IP: {}".format(self.ue_ip))

    def _setup_ip_interface(self):
        if self.uecontrol.is_ip_interface_setup_supported():
            self.logger.debug(
                "Setting up IP interface to: ip_version {}, network interface name pattern '{}'".format(self.ip_version,
                                                                                                        self.network_interface_name))
            self.uecontrol.set_ip_interface_for_mobile_data(ip_version=self.ip_version,
                                                            interface_name_pattern=self.network_interface_name)
            self.logger.debug("IP interface setup completed.")

    def get_server_ip(self):
        """
        Get server IP address.

        :return: ip of iperf's server
        """
        if self.dt_config.is_downlink():
            return self.ue_ip
        if self.dt_config.is_uplink():
            if self._has_iperf_interface_ip():
                return self.dt_config.app_server['iperf_interface_ip']
            return self.dt_config.app_server['host']
        raise Exception("not impl")

    def get_network_interface(self):
        """
        Get iperf_interface_name param from config
        :return: iperf_interface_name param value or None if config param not exists
        """
        return self.dt_config.get_iperf_interface_name()

    def get_ip_version(self):
        if self.dt_config.app_server['ip_version']:
            return self.dt_config.app_server['ip_version']
        else:
            return '4'

    def get_apn(self):
        """
        Get APN specified as an argument or in config
        Please bare in mind that an argument takes precedence over the config
        """
        apn = self.dt_config.robot_kwargs.get("apn")
        if apn:
            self.logger.debug("APN found in argument: {}".format(apn))
            return apn
        else:
            self.logger.debug("APN not specified in argument")
            return None

    def run_cmd_on_server(self, cmd, echo_pid=True, blocking=False, expect_output=False, get_pty=False):
        """
        Run command on iperf server endpoint
        :param cmd: command to execute
        :param echo_pid: if True, adds echo $$ ;before executed cmd
        :param blocking: waits for output and returns lines
        :param expect_output: if True expects non empty output
        :param get_pty: run with interactive session - sometimes ssh fail to return cmd output when 'False'
        """
        if self.dt_config.is_downlink():
            # DL: UE = server
            return self.run_cmd_on_ue(cmd, echo_pid=echo_pid, blocking=blocking, expect_output=expect_output)
        # UL: ssh = server
        ip = self._get_app_server_ip()
        return self.run_cmd_on_ssh(cmd, ip, echo_pid=echo_pid, blocking=blocking, expect_output=expect_output,
                                   get_pty=get_pty)

    def run_cmd_on_client(self, cmd, echo_pid=True, blocking=False, expect_output=False):
        """
        Run command on iperf client endpoint
        :param cmd: command to execute
        :param echo_pid: if True, adds echo $$ ;before executed cmd
        :param blocking: waits for output and returns lines
        :param expect_output: if True expects non empty output
        """
        if self.dt_config.is_downlink():
            # DL: ssh = client
            ip = self._get_app_server_ip()
            return self.run_cmd_on_ssh(cmd, ip, echo_pid=echo_pid, blocking=blocking, expect_output=expect_output)
        # UL: UE = client
        return self.run_cmd_on_ue(cmd, echo_pid=echo_pid, blocking=blocking, expect_output=expect_output)

    def get_iperf_fullpath_on_ue(self):
        """Method's name says everything."""
        if self.dt_config.iperf_path:
            return self.dt_config.get_corrected_iperf_path(version=self.dt_config.iperf_version)
        return self.uecontrol.get_iperf_fullpath(version=self.dt_config.iperf_version)

    def get_iperf_server_binary_fullpath(self):
        """
        Get iperf server file name.

        :return: filename of iperf to run in server's cmd.
        """
        if self.dt_config.is_downlink():
            # downlink: UE = server
            return self.get_iperf_fullpath_on_ue()
        if self.dt_config.is_uplink():
            # uplink: ssh = server
            return self.dt_config.get_iperf_execution_file_name(version=self.dt_config.iperf_version)
        raise NotImplementedError('impl supports downlink xor uplink')

    def get_iperf_client_binary_fullpath(self):
        """
        Get iperf client file name.

        :return: filename of iperf to run in client's cmd.
        """
        if self.dt_config.is_downlink():
            # downlink: ssh = clinet
            return self.dt_config.get_iperf_execution_file_name(version=self.dt_config.iperf_version)
        if self.dt_config.is_uplink():
            # uplink: UE = client
            return self.get_iperf_fullpath_on_ue()
        raise NotImplementedError('impl supports downlink xor uplink')

    def _get_app_server_ip(self):
        return self.dt_config.app_server['host']

    def run_cmd_on_ssh(self, cmd, ip, echo_pid=True, blocking=False, expect_output=False, get_pty=False):
        """
        Runs command on ssh endpoint (iperf app server)
        :param cmd: command to execute
        :param ip: host ip to run command on
        :param echo_pid: if True, adds echo $$ ;before executed cmd
        :param blocking: waits for output and returns lines
        :param expect_output: if True expects non empty output
        :param get_pty: run with interactive session - sometimes ssh fail to return cmd output when 'False'
        :return:
        """
        if echo_pid:
            cmd = 'echo $$; {}'.format(cmd)
        self.logger.debug("Run SSH cmd on {}: {}".format(ip, cmd))
        if blocking:
            return self.ssh_manager.run_cmd_and_get_output_lines(cmd, ip, expect_output=expect_output, get_pty=get_pty)
        return self.ssh_manager.run_cmd_and_get_non_blocking_reader(cmd, ip)

    def run_cmd_on_ue(self, cmd, echo_pid=True, blocking=False, expect_output=False):
        """
        Runs command on UE and displays process id if needed
        :param cmd: command to execute
        :param echo_pid: if True, adds echo $$ ;before executed cmd
        :param blocking: waits for output and returns lines
        :param expect_output: if True expects non empty output
        :return:
        """
        if str(self.dt_config.iperf_mode).lower() == 'adb':  # TODO: it can be executed only on AtCmdsUe class
            if echo_pid:
                cmd = "adb -s {} shell 'echo $$; {}'".format(self.dt_config.serial_number, cmd)
        else:
            if echo_pid:
                cmd = 'echo $$; {}'.format(cmd)
        self.logger.debug("Run cmd on {}: {}".format(type(self.uecontrol), cmd))
        if blocking:
            return self.uecontrol.run_cmd_and_get_output_lines(cmd, expect_output=expect_output)
        return self.uecontrol.run_cmd_and_get_non_blocking_output(cmd)

    def special_server_run_options(self):
        """
        Options to be added to cmd
        :return:
        """
        options = []
        self.add_bind_option_server(options)

        self.add_iperf_len_option_server(options)

        if self.dt_config.is_ipv6_required():
            options.append('-V')

        return ' '.join(options + self.dt_config.additional_iperf_options_server)

    def add_iperf_len_option_server(self, options):
        """Adds -l option on server"""
        if self._has_iperf_len():
            add_iperf_len = '-l {}'.format(self.dt_config.app_server['iperf_len'])
            options.append(add_iperf_len)

    def add_bind_option_server(self, options):
        """Adds direction specific iperf -B option on server which binds the iperf to provided IP."""
        if self.dt_config.is_uplink():
            # uplink: ssh = server
            if self._has_iperf_interface_ip():
                bind_to_ip = '-B {}'.format(self.dt_config.app_server['iperf_interface_ip'])
                options.append(bind_to_ip)
        if self.dt_config.is_downlink() and self._use_binding():
            # downlink: iperf / app server (ssh)
            bind_to_ip = '-B {}'.format(self.ue_ip)
            options.append(bind_to_ip)

    def special_client_run_options(self):
        """
        Options to be added to cmd
        :return:
        """
        options = []
        self.add_bind_option_client(options)

        if self.dt_config.is_ipv6_required():
            options.append('-V')

        return ' '.join(options + self.dt_config.additional_iperf_options_client)

    def add_bind_option_client(self, options):
        """Adds direction specific iperf -B option on client which binds the iperf to provided IP."""
        if self.dt_config.is_downlink():
            # downlink: iperf / app server (ssh)
            if self._has_iperf_interface_ip():
                option_b = '-B {}'.format(self.dt_config.app_server['iperf_interface_ip'])
                options.append(option_b)
        if self.dt_config.is_uplink():
            # uplink: UE / UE_PC
            if self._use_binding() and self.dt_config.iperf_version == 2:
                option_b = '-B {}'.format(self.ue_ip)
                options.append(option_b)
        return options

    def is_able_to_linux_like_process_kill(self):
        """?"""
        return self.uecontrol.is_able_to_linux_like_process_kill()

    def create_iperf_server_cmd(self, port):
        """
        Create iperf command to run on iperf server side
        :param port:
        :return:
        """
        result = '{iperf} --version; {iperf} -s {udp} -p {port} -i {interval} {special_options} {forceflush} 2>&1'.format(
            iperf=self.get_iperf_server_binary_fullpath(),
            udp=self._udp_server_option(),
            port=str(port),
            interval=self.dt_config.get_iperf_interval(),
            special_options=self.special_server_run_options(),
            forceflush="--forceflush" if self.dt_config.iperf_version == 3 else "")
        self.logger.debug("Iperf server CMD: " + result)
        return result

    def create_iperf_client_cmd(self, port):
        """
        Create iperf command to run on iperf client side
        :param port:
        :return:
        """
        result = '{iperf} --version; {iperf} -c {server_ip} {udp} {bandwidth} -p {port} -t {duration} -i {interval} ' \
                 '{special_options} {forceflush} 2>&1'.format(iperf=self.get_iperf_client_binary_fullpath(),
                                                              server_ip=self.get_server_ip(),
                                                              udp=self._udp_client_option(),
                                                              bandwidth=self._bandwidth_option(),
                                                              interval=self.dt_config.get_iperf_interval(),
                                                              port=str(port),
                                                              duration=str(self.dt_config.get_duration()),
                                                              special_options=self.special_client_run_options(),
                                                              forceflush="--forceflush" if self.dt_config.iperf_version == 3 else "")
        self.logger.debug("iperf client CMD: {} ".format(result))
        return result

    def _bandwidth_option(self):
        bandwidth = self.dt_config.get_bandwidth()
        if bandwidth:
            return '-b {}'.format(bandwidth)
        return ''

    def _udp_server_option(self):
        if self.dt_config.iperf_version == 2 and self.dt_config.is_udp():
            return '-u'
        return ''

    def _udp_client_option(self):
        if self.dt_config.is_udp():
            return '-u'
        return ''

    def _has_iperf_interface_ip(self):
        if self.dt_config.app_server.get('iperf_interface_ip'):
            self.logger.debug("_has_iperf_interface_ip iperf_interface_ip: {}".format(
                self.dt_config.app_server['iperf_interface_ip']))
            return True
        return False

    def _has_iperf_len(self):
        if self.dt_config.app_server.get('iperf_len'):
            self.logger.debug("_has_iperf_len: {}".format(
                self.dt_config.app_server['iperf_len']))
            return True
        return False

    def _use_binding(self):
        if self.dt_config.iperf_bind_ue_ip is None:
            return True
        return self.dt_config.iperf_bind_ue_ip
